mapper.select:
UPDATE pf.workspace_environment_operation SET observation_owner=#{observerId},observation_until=clock_timestamp()+interval '30 seconds',
    observation_revision=observation_revision+1
WHERE id=#{command.operationId} AND command_id=#{command.commandId} AND space_id=#{command.spaceId}
    AND workspace_id=#{command.workspaceId} AND environment_id=#{command.environmentId}
    AND owner_id=#{command.ownerId} AND generation=#{command.generation} AND fence=#{command.fence}
    AND protocol='ENVIRONMENT_V3' AND(status='UNKNOWN' OR(status IN('CLAIMED','RUNNING')
        AND(lease_until<=clock_timestamp() OR deadline_at<=clock_timestamp())))
    AND(observation_until IS NULL OR observation_until<=clock_timestamp())
RETURNING observation_owner AS observer_id,observation_revision AS revision

SELECT EXISTS(SELECT 1 FROM pf.workspace_environment_operation WHERE id=#{command.operationId}
    AND command_id=#{command.commandId} AND space_id=#{command.spaceId} AND workspace_id=#{command.workspaceId}
    AND environment_id=#{command.environmentId} AND owner_id=#{command.ownerId} AND generation=#{command.generation}
    AND fence=#{command.fence} AND protocol='ENVIRONMENT_V3' AND observation_until>clock_timestamp()
    AND observation_owner=#{observerId}
    AND observation_revision=#{revision}
    AND(status='UNKNOWN' OR(status IN('CLAIMED','RUNNING')
        AND(lease_until<=clock_timestamp() OR deadline_at<=clock_timestamp()))))

mapper.update:
UPDATE pf.workspace_environment_operation SET status=#{receipt.state},effect_state=#{receipt.effectState},error_code=#{receipt.errorCode},version=version+1,
    cleanup_state=CASE WHEN cleanup_required AND #{receipt.revision}=2 THEN 'CONFIRMED' ELSE cleanup_state END
WHERE id=#{observation.command.operationId} AND command_id=#{observation.command.commandId}
    AND space_id=#{observation.command.spaceId} AND workspace_id=#{observation.command.workspaceId}
    AND environment_id=#{observation.command.environmentId} AND generation=#{observation.command.generation}
    AND fence=#{observation.command.fence} AND owner_id=#{observation.command.ownerId}
    AND observation_owner=#{observation.observerId} AND observation_revision=#{observation.revision}
    AND observation_until>clock_timestamp() AND status IN('UNKNOWN','CLAIMED','RUNNING')

mapper.select:
SELECT s.container_id,s.image_id AS image,s.container_started_at AS started_at,
    s.container_finished_at AS finished_at,s.exec_stopped,s.callbacks_stopped,s.observed_at
FROM pf.workspace_environment_operation o JOIN pf.workspace_environment_stop_receipt s ON s.id=o.prior_stop_receipt_id
WHERE o.id=#{command.operationId} AND o.space_id=#{command.spaceId} AND o.workspace_id=#{command.workspaceId}
    AND o.environment_id=#{command.environmentId} AND o.generation=#{command.generation}
    AND s.space_id=o.space_id AND s.workspace_id=o.workspace_id AND s.environment_id=o.environment_id
    AND s.generation=o.generation AND s.container_id=#{command.containerId} AND s.image_id=#{command.imageId}
    AND s.container_started_at=#{command.containerStartedAt} AND s.exec_stopped AND s.callbacks_stopped

SELECT id FROM pf.workspace_environment_stop_receipt WHERE space_id=#{command.spaceId}
    AND workspace_id=#{command.workspaceId} AND environment_id=#{command.environmentId}
    AND operation_id=#{command.operationId} AND generation=#{command.generation} AND fence=#{command.fence}
    AND container_id=#{command.containerId} AND image_id=#{command.imageId}
    AND container_started_at=#{command.containerStartedAt} AND exec_stopped AND callbacks_stopped

SELECT EXISTS(SELECT 1 FROM pf.workspace_environment_cleanup WHERE command_id=#{command.commandId}
    AND operation_id=#{command.operationId} AND space_id=#{command.spaceId} AND workspace_id=#{command.workspaceId}
    AND environment_id=#{command.environmentId} AND generation=#{command.generation} AND fence=#{command.fence}
    AND outcome='CONFIRMED' AND container_id=#{command.containerId} AND image_id=#{command.imageId}
    AND container_started_at=#{command.containerStartedAt})

mapper.update:
UPDATE pf.workspace_environment_command SET result_revision=2,result_runner_instance_id=#{runnerId}
WHERE command_id=#{command.commandId} AND operation_id=#{command.operationId} AND owner_id=#{command.ownerId}
    AND generation=#{command.generation} AND fence=#{command.fence} AND result_revision=1 AND state IN('COMMITTED','FAILED')

UPDATE pf.workspace_environment SET state=#{state},error_code=#{receipt.errorCode},version=version+1,updated_at=clock_timestamp(),last_activity_at=clock_timestamp()
        ,container_id=#{receipt.container.id},container_started_at=#{receipt.container.startedAt},readiness_hash=#{receipt.container.readinessHash}
        WHERE id=#{command.environmentId} AND space_id=#{command.spaceId} AND workspace_id=#{command.workspaceId} AND operation_id=#{command.operationId} AND generation=#{command.generation} AND fence=#{command.fence}
